public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n == 1) {
        return false;
    }

    int sum = 0;
    for (int num : nums) {
        sum += num;
    }

    boolean[] dp = new boolean[sum + 1];
    dp[0] = true;

    for (int num : nums) {
        for (int j = sum; j >= num; j--) {
            dp[j] = dp[j] || dp[j - num];
        }
    }

    for (int i = 1; i <= (n / 2); i++) {
        if (sum * i % n == 0 && dp[sum * i / n]) {
            return true;
        }
    }

    return false;
}

